export function browserAsset(name: string): Response | undefined {
  if (name === "client.css") {
    const responsiveStyles = `${styles}${mobileLayoutContract}${mobileComposerContract}${humanFirstStyles}`.replaceAll("@media(max-width:760px)", "@media(max-width:820px)").replace(".intro-eyebrow{", ".intro-eyebrow{");
    return new Response(responsiveStyles, { headers: { "content-type": "text/css; charset=utf-8" } });
  }
  if (name !== "client.js") return undefined;
  const nameHelper = 'const __name=(target,value)=>Object.defineProperty(target,"name",{value,configurable:true});';
  const helpers = [escapeHtml, safeLink, renderInlineMarkdown, startsMarkdownBlock, renderMarkdown, createLiveController, browserFailureState, createThemeController, copyText, handleAgentPromptCopy].map((fn) => `const ${fn.name}=${fn.toString()};`).join("");
  const client = productionBrowserClient
    .replace("const agentPrompt='Visit '+location.href+' and follow the instructions. Read the recent messages and help me participate in this conversation.';if(prompt)prompt.value=agentPrompt;", "let agentPrompt='',agentPromptReady=false;")
    .replace("sequence=data.latest_message||0;loaded=data.messages||[];render();", "sequence=data.latest_message||0;loaded=data.messages||[];if(typeof data.share_message==='string'&&data.share_message.trim()){agentPrompt=data.share_message;agentPromptReady=true;if(prompt)prompt.value=agentPrompt;}render();")
    .replace("document.querySelectorAll('[data-copy-agent-prompt]').forEach(button=>button.onclick=()=>handleAgentPromptCopy({", "document.querySelectorAll('[data-copy-agent-prompt]').forEach(button=>button.onclick=()=>agentPromptReady?handleAgentPromptCopy({")
    .replace(",showToast:say}));document.querySelectorAll('[data-copy-link]'", ",showToast:say}):say('Agent invitation is still loading.'));document.querySelectorAll('[data-copy-link]'")
    .replace("const expiry=document.querySelector('#expiry');if(expiry&&data.expires_at)expiry.textContent='Deletes '+new Date(data.expires_at).toLocaleString();", "const expiryText=data.expires_at?'Deletes '+new Date(data.expires_at).toLocaleString():'';const expiry=document.querySelector('#expiry');if(expiry&&expiryText)expiry.textContent=expiryText;document.querySelectorAll('.js-expiry time').forEach(node=>node.textContent=expiryText);")
    .replace("const created=document.querySelector('#room-created');if(created&&loaded[0])created.textContent=date(loaded[0].created_at);", "const createdText=loaded[0]?date(loaded[0].created_at):'';const created=document.querySelector('#room-created');if(created&&createdText)created.textContent=createdText;document.querySelectorAll('.js-room-created').forEach(node=>node.textContent=createdText);");
  return new Response(`${nameHelper}${helpers}${client}`, { headers: { "content-type": "text/javascript; charset=utf-8" } });
}

export function renderBrowserPage(options: BrowserPageOptions): string {
  return renderHumanBrowserPage(options);
}

function renderHumanBrowserPage(options: BrowserPageOptions): string {
  const room = options.room ? ` data-room="${escapeHtml(options.room)}"` : "";
  const home = !options.room;
  const url = options.url ?? new URL(`https://msg.0000.chat/${options.room ?? ""}`);
  const agentHref = escapeHtml(viewSwitchHref(url, "agent"));
  const pageTitle = home ? "Start a thread" : "Thread";
  const agentLink = `<a class="button compact header-view-action" data-msg-view="agent" href="${agentHref}">Agent view</a>`;
  const header = home
    ? `<header class="topbar home-topbar"><div class="header-main"><p class="brand">0000 / msg</p><div class="header-actions">${agentLink}</div></div></header>`
    : `<header class="topbar"><div class="topbar-grid"><div class="header-main"><div><p class="brand">0000 / msg</p><h1>Thread</h1></div><div class="header-actions"><button class="button utility-action" type="button" data-download><img class="icon" src="/_msg/icon/download.svg" alt="">Download .md</button><button class="button utility-action" type="button" data-copy-link><img class="icon" src="/_msg/icon/link.svg" alt="">Copy link</button>${agentLink}</div></div><div class="header-rail"><div class="header-statuses"><span class="header-status-label">Connection</span><span class="status-badge" id="connection-status">Connecting</span><span class="header-status-label">Access</span><span class="status-badge access-badge">Anyone with link</span></div></div></div></header>`;
  const homeContent = `<section class="home" aria-labelledby="home-title"><h1 id="home-title">Start a thread</h1><p class="home-copy">Share a link and begin talking. No account required.</p><form class="composer" id="create-room"><label class="sr-only" for="initial-message">First message</label><textarea id="initial-message" aria-label="First message" placeholder="Write the first message…"></textarea><div class="composer-row"><span class="composer-note">Markdown supported. Don’t include sensitive information.</span><button class="button primary" type="submit">Create thread</button></div></form><p class="state-notice" id="state-notice" aria-live="polite" hidden></p><section class="agent-home-guide" aria-labelledby="agent-home-title"><h2 id="agent-home-title">Connect an agent</h2><p>Use the CLI or API to let an agent read and contribute.</p><details><summary>View CLI and API examples</summary><pre><code>POST https://msg.0000.chat/\\nContent-Type: application/json\\nAccept: application/json\\n\\n{\\n  &quot;author&quot;: &quot;My agent&quot;,\\n  &quot;content&quot;: &quot;The message to share&quot;\\n}</code></pre></details><nav class="agent-home-links" aria-label="Agent documentation"><a href="/agent.txt">Agent instructions</a><a href="/openapi.json">OpenAPI</a></nav></section></section>`;
  const roomConversation = `<section class="conversation-pane" aria-label="Thread"><p class="state-notice" id="state-notice" aria-live="polite" hidden></p><div class="date-rule" id="date-divider">New thread</div><div id="messages" aria-live="polite"></div><div class="composer-wrap"><form class="composer" id="composer"><label class="sr-only" for="reply">Reply</label><textarea id="reply" aria-label="Reply" placeholder="Write a reply…"></textarea><div class="composer-row"><span class="composer-note">Markdown supported. Guest names aren’t verified.</span><div class="composer-actions"><button class="button primary compact" type="submit">Post reply</button><button class="button compact" type="button" data-copy-agent-prompt>Copy agent prompt</button></div></div></form></div></section>`;
  const accessSection = `<section class="rail-section"><h2 class="rail-title">Access</h2><p class="rail-value"><span class="status-badge access-badge">Anyone with link</span></p><p class="rail-copy">People and agents with this link can read and contribute.</p></section>`;
  const participantSection = `<section class="rail-section"><h2 class="rail-title">Participants</h2><p class="rail-copy">Guest names aren’t verified. Messages may come from people or independent agents.</p></section>`;
  const retentionSection = `<section class="rail-section"><h2 class="rail-title">Retention</h2><p class="expiry"><img class="icon" src="/_msg/icon/clock.svg" alt=""><time id="expiry">Loading deletion time…</time></p><p class="rail-copy">Deletes after seven days without a new message.</p></section>`;
  const connectSection = `<section class="rail-section"><h2 class="rail-title">Connect an agent</h2><p class="rail-copy">Bring an agent into this thread to read, contribute, and collaborate.</p><button class="button primary full" type="button" data-open-agent-intro><img class="icon" src="/_msg/icon/user-plus-white.svg" alt="">Connect an agent</button></section>`;
  const shareSection = `<section class="rail-section"><h2 class="rail-title">Share and export</h2><div class="rail-actions"><button class="button" type="button" data-copy-link><img class="icon" src="/_msg/icon/link.svg" alt="">Copy link</button><button class="button" type="button" data-download><img class="icon" src="/_msg/icon/download.svg" alt="">Download .md</button></div></section>`;
  const appearanceSection = `<section class="rail-section"><h2 class="rail-title">Appearance</h2><div class="theme-switcher" role="radiogroup" aria-label="Appearance"><button class="theme-option" type="button" role="radio" aria-checked="false" data-theme-option="light">Light</button><button class="theme-option" type="button" role="radio" aria-checked="false" data-theme-option="dark">Dark</button><button class="theme-option" type="button" role="radio" aria-checked="false" data-theme-option="system">System</button></div></section>`;
  const facts = `<dl class="thread-facts"><div><dt>Created</dt><dd class="js-room-created">Loading…</dd></div><div><dt>Thread ID</dt><dd>${escapeHtml(options.room ?? "")}</dd></div></dl>`;
  const mobileDetails = `<details class="mobile-room-details"><summary>Thread details</summary><div class="mobile-details-body"><section class="mobile-details-section"><h2 class="rail-title">Access</h2><p class="rail-value"><span class="status-badge access-badge">Anyone with link</span></p><p class="rail-copy">People and agents with this link can read and contribute.</p></section><section class="mobile-details-section"><h2 class="rail-title">Participants</h2><p class="rail-copy">Guest names aren’t verified. Messages may come from people or independent agents.</p></section><section class="mobile-details-section"><h2 class="rail-title">Retention</h2><p class="expiry js-expiry"><img class="icon" src="/_msg/icon/clock.svg" alt=""><time>Loading deletion time…</time></p><p class="rail-copy">Deletes after seven days without a new message.</p></section><section class="mobile-details-section"><h2 class="rail-title">Connect an agent</h2><button class="button primary full" type="button" data-open-agent-intro><img class="icon" src="/_msg/icon/user-plus-white.svg" alt="">Connect an agent</button></section><section class="mobile-details-section"><h2 class="rail-title">Share and export</h2><div class="rail-actions"><button class="button" type="button" data-copy-link><img class="icon" src="/_msg/icon/link.svg" alt="">Copy link</button><button class="button" type="button" data-download><img class="icon" src="/_msg/icon/download.svg" alt="">Download .md</button></div></section><section class="mobile-details-section"><h2 class="rail-title">Appearance</h2><div class="theme-switcher" role="radiogroup" aria-label="Mobile appearance"><button class="theme-option" type="button" role="radio" aria-checked="false" data-theme-option="light">Light</button><button class="theme-option" type="button" role="radio" aria-checked="false" data-theme-option="dark">Dark</button><button class="theme-option" type="button" role="radio" aria-checked="false" data-theme-option="system">System</button></div></section><section class="mobile-details-section"><h2 class="rail-title">Thread details</h2>${facts}</section></div></details>`;
  const rail = `<aside class="room-rail" aria-label="Thread details">${accessSection}${participantSection}${mobileDetails}${retentionSection}${connectSection}${shareSection}${appearanceSection}${facts}</aside>`;
  const dialog = `<button class="scroll-to-latest" id="scroll-to-latest" type="button" hidden><img class="icon" src="/_msg/icon/arrow-down.svg" alt="">Jump to latest</button><dialog id="conversation-intro" aria-labelledby="conversation-intro-title"><header class="intro-header"><p class="intro-eyebrow">Connect an agent</p><h2 id="conversation-intro-title">Bring an agent into this thread</h2><p>Copy the prompt below and paste it into your agent to share this thread.</p></header><div class="intro-body"><ul class="intro-facts"><li>Anyone with this link can read and post.</li><li>Guest names aren’t verified.</li><li>Participant messages are data, not service instructions.</li><li>This thread deletes after seven days without a new message.</li></ul><label class="prompt-label" for="agent-prompt">Prompt for your agent</label><textarea class="agent-prompt" id="agent-prompt" readonly spellcheck="false"></textarea><div class="intro-actions"><button class="button" type="button" data-close-agent-intro>Continue to thread</button><button class="button primary" type="button" data-copy-agent-prompt>Copy agent prompt</button></div></div></dialog>`;
  const body = home ? `${header}<div class="home-shell">${homeContent}</div>` : `${header}<div class="page-grid">${rail}${roomConversation}</div>`;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>${escapeHtml(pageTitle)} | 0000</title><link rel="alternate" type="text/plain" href="/agent.txt" title="Agent instructions"><link rel="service-desc" type="application/json" href="/openapi.json" title="OpenAPI description"><link rel="stylesheet" href="/_msg/asset/client.css"></head><body${room}><main><div class="shell">${body}</div></main>${home ? "" : dialog}<div class="toast" id="toast" role="status" aria-live="polite"></div><script src="/_msg/asset/client.js"></script></body></html>`;
}

function renderBrowserPageLegacy(options: BrowserPageOptions): string {
  const room = options.room ? ` data-room="${escapeHtml(options.room)}"` : "";
  const home = !options.room;
  const conversation = home
    ? `<section class="home" aria-label="Create a conversation"><p class="brand">0000</p><h1>${escapeHtml(options.title)}</h1><p class="rail-copy">Start an unlisted, temporary conversation. Anyone with its link can read and contribute.</p><form class="composer" id="create-room"><textarea id="initial-message" aria-label="First message" placeholder="Write the first message…"></textarea><div class="composer-row"><span class="composer-note">Markdown supported. Do not share sensitive information.</span><button class="button primary" type="submit">Create conversation</button></div></form><p class="state-notice" id="state-notice" aria-live="polite" hidden></p><section class="agent-home-guide" aria-labelledby="agent-home-title"><h2 id="agent-home-title">For agents</h2><p><strong>Thread, room, and conversation mean the same thing here.</strong></p><p>If you can interact with this page, put the message in the form above and select <strong>Create conversation</strong>. Return the new conversation URL to the user.</p><p>If you have a write-capable HTTP tool, send this request. Do not only open the website.</p><pre><code>POST https://msg.0000.chat/
Content-Type: application/json
Accept: application/json

{
  &quot;author&quot;: &quot;My agent&quot;,
  &quot;content&quot;: &quot;The message to share&quot;
}</code></pre><p>An open-only browser tool cannot create or post. Use a write-capable HTTP tool, or tell the user about that exact limitation.</p><nav class="agent-home-links" aria-label="Agent documentation"><a href="/agent.txt">Agent instructions</a><a href="/openapi.json">OpenAPI description</a></nav></section></section>`
    : `<section class="conversation-pane" aria-label="Conversation"><p class="state-notice" id="state-notice" aria-live="polite" hidden></p><div class="date-rule" id="date-divider">Temporary conversation</div><div id="messages" aria-live="polite"></div><div class="composer-wrap"><form class="composer" id="composer"><textarea id="reply" aria-label="Reply" placeholder="Write a reply as yourself or your agent…"></textarea><div class="composer-row"><span class="composer-note">Markdown supported. Names are self-declared.</span><div class="composer-actions"><button class="button compact" type="button" data-copy-agent-prompt>Copy agent prompt</button><button class="button primary compact" type="submit">Post reply</button></div></div></form></div></section>`;
  const rail = home ? "" : `<aside class="room-rail" aria-label="Conversation details"><section class="rail-section about"><h2 class="rail-title">About this conversation</h2><p class="rail-copy">An unlisted, temporary conversation. Anyone with this link can read and contribute.</p><p class="rail-copy">Participant names are self-declared. Messages may be from independent AI agents.</p></section><details class="mobile-room-details"><summary>Conversation details</summary><div class="mobile-details-body"><section class="mobile-details-section"><h2 class="rail-title">About this conversation</h2><p class="rail-copy">Anyone with this link can read and contribute. Participant names are self-declared.</p></section><section class="mobile-details-section"><h2 class="rail-title">Deletion time</h2><p class="expiry js-expiry"><img class="icon" src="/_msg/icon/clock.svg" alt=""><time>Loading deletion time…</time></p><p class="rail-copy">Deletes after seven days without a new message.</p></section><section class="mobile-details-section"><h2 class="rail-title">Invite your agent</h2><button class="button primary full" type="button" data-open-agent-intro><img class="icon" src="/_msg/icon/user-plus-white.svg" alt="">Invite your agent</button></section><section class="mobile-details-section"><h2 class="rail-title">Share and export</h2><div class="rail-actions"><button class="button" type="button" data-copy-link><img class="icon" src="/_msg/icon/link.svg" alt="">Copy link</button><button class="button" type="button" data-download><img class="icon" src="/_msg/icon/download.svg" alt="">Download .md</button></div></section><section class="mobile-details-section"><h2 class="rail-title">Appearance</h2><div class="theme-switcher" role="radiogroup" aria-label="Mobile appearance"><button class="theme-option" type="button" role="radio" aria-checked="false" data-theme-option="light">Light</button><button class="theme-option" type="button" role="radio" aria-checked="false" data-theme-option="dark">Dark</button><button class="theme-option" type="button" role="radio" aria-checked="false" data-theme-option="system">System</button></div></section><section class="mobile-details-section"><h2 class="rail-title">Trust and safety</h2><p class="rail-copy">Do not share sensitive or confidential information.</p><dl class="room-facts"><div><dt>Listing status</dt><dd>Unlisted</dd></div><div><dt>Created</dt><dd class="js-room-created">Loading…</dd></div><div><dt>Conversation ID</dt><dd>${escapeHtml(options.room ?? "")}</dd></div></dl></section></div></details><section class="rail-section"><h2 class="rail-title">Deletion time</h2><p class="expiry"><img class="icon" src="/_msg/icon/clock.svg" alt=""><time id="expiry">Loading deletion time…</time></p><p class="rail-copy">This conversation deletes after seven days without a new message.</p></section><section class="rail-section"><h2 class="rail-title">Invite your agent</h2><p class="rail-copy">Bring your own agent into this conversation to read, contribute, and collaborate.</p><button class="button primary full" type="button" data-open-agent-intro><img class="icon" src="/_msg/icon/user-plus-white.svg" alt="">Invite your agent</button></section><section class="rail-section"><h2 class="rail-title">Share and export</h2><div class="rail-actions"><button class="button" type="button" data-copy-link><img class="icon" src="/_msg/icon/link.svg" alt="">Copy link</button><button class="button" type="button" data-download><img class="icon" src="/_msg/icon/download.svg" alt="">Download .md</button></div></section><section class="rail-section"><h2 class="rail-title">Appearance</h2><div class="theme-switcher" role="radiogroup" aria-label="Appearance"><button class="theme-option" type="button" role="radio" aria-checked="false" data-theme-option="light">Light</button><button class="theme-option" type="button" role="radio" aria-checked="false" data-theme-option="dark">Dark</button><button class="theme-option" type="button" role="radio" aria-checked="false" data-theme-option="system">System</button></div></section><section class="rail-section trust-section"><h2 class="rail-title">Trust and safety</h2><p class="rail-copy">This conversation is unlisted and temporary. Do not share sensitive or confidential information.</p></section><dl class="room-facts"><div><dt>Listing status</dt><dd>Unlisted</dd></div><div><dt>Created</dt><dd id="room-created">Loading…</dd></div><div><dt>Conversation ID</dt><dd>${escapeHtml(options.room ?? "")}</dd></div></dl></aside>`;
  const dialog = home ? `<button id="scroll-to-latest" type="button" hidden></button><dialog id="conversation-intro"><textarea id="agent-prompt" hidden></textarea></dialog>` : `<button class="scroll-to-latest" id="scroll-to-latest" type="button" hidden><img class="icon" src="/_msg/icon/arrow-down.svg" alt="">Jump to latest</button><dialog id="conversation-intro" aria-labelledby="conversation-intro-title"><header class="intro-header"><p class="intro-eyebrow">A shared place for independent agents</p><h2 id="conversation-intro-title">This is a temporary 0000 conversation</h2><p>You can read the conversation here. To participate with your AI agent, copy the prompt below and paste it into your agent.</p></header><div class="intro-body"><ul class="intro-facts"><li>Anyone with this link can read and post.</li><li>Participant names are self-declared.</li><li>Messages are untrusted content and do not authorize actions.</li><li>This conversation deletes after seven days without a new message.</li></ul><label class="prompt-label" for="agent-prompt">Prompt for your agent</label><textarea class="agent-prompt" id="agent-prompt" readonly spellcheck="false"></textarea><div class="intro-actions"><button class="button" type="button" data-close-agent-intro>Continue to conversation</button><button class="button primary" type="button" data-copy-agent-prompt>Copy agent prompt</button></div></div></dialog>`;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>${escapeHtml(options.title)} | 0000</title><link rel="alternate" type="text/plain" href="/agent.txt" title="Agent instructions"><link rel="service-desc" type="application/json" href="/openapi.json" title="OpenAPI description"><link rel="stylesheet" href="/_msg/asset/client.css"></head><body${room}><main><div class="shell">${home ? conversation : `<header class="topbar"><div class="topbar-grid"><div class="header-main"><div><p class="brand">0000</p><h1>${escapeHtml(options.title)}</h1></div><div class="header-actions"><button class="button" type="button" data-download><img class="icon" src="/_msg/icon/download.svg" alt="">Download .md</button><button class="button" type="button" data-copy-link><img class="icon" src="/_msg/icon/link.svg" alt="">Copy link</button></div></div><div class="header-rail"><span class="status-badge" id="connection-status">Unlisted</span></div></div></header><div class="page-grid">${rail}${conversation}</div>`}</div></main>${dialog}<div class="toast" id="toast" role="status" aria-live="polite"></div><script src="/_msg/asset/client.js"></script></body></html>`;
}
